export type ShenqiGodName = keyof typeof SHENQI_EFFECTS;

export interface ShenqiGodAttributes {
  readonly 力道: number;
  readonly 体魄: number;
  readonly 身法: number;
  readonly 灵力: number;
  readonly 神识: number;
  readonly 根骨: number;
}

/**
 * 神契古神的固定人物六维。
 * 胧沿用剧情模式开场快照；其余依据角色位阶与道争定位固化，避免沙盒开场由 AI 猜测或写成全 0。
 */
export const SHENQI_GOD_ATTRIBUTES = {
  莫尔迦: { 力道: 70, 体魄: 82, 身法: 60, 灵力: 92, 神识: 100, 根骨: 88 },
  维拉: { 力道: 45, 体魄: 70, 身法: 88, 灵力: 90, 神识: 92, 根骨: 78 },
  斯芬克丝: { 力道: 40, 体魄: 62, 身法: 55, 灵力: 86, 神识: 98, 根骨: 80 },
  拉维妮亚: { 力道: 72, 体魄: 78, 身法: 84, 灵力: 88, 神识: 92, 根骨: 86 },
  克茜拉: { 力道: 65, 体魄: 80, 身法: 68, 灵力: 95, 神识: 90, 根骨: 88 },
  奈亚: { 力道: 75, 体魄: 78, 身法: 100, 灵力: 95, 神识: 100, 根骨: 90 },
  胧: { 力道: 20, 体魄: 25, 身法: 70, 灵力: 45, 神识: 60, 根骨: 35 },
} as const satisfies Record<ShenqiGodName, ShenqiGodAttributes>;

const ATTRIBUTE_KEYS = ['力道', '体魄', '身法', '灵力', '神识', '根骨'] as const;

type ShenqiSnapshot = {
  六维?: Partial<Record<(typeof ATTRIBUTE_KEYS)[number], unknown>>;
  气血?: unknown;
  法力值?: unknown;
  气血上限?: unknown;
  法力值上限?: unknown;
};

/** 固定神契古神的资源上限（固定档案常量，直接写死，不再计算）。 */
const SHENQI_MAX_VITALS: Record<ShenqiGodName, { 气血: number; 法力值: number }> = {
  莫尔迦: { 气血: 1310, 法力值: 1870 },
  维拉: { 气血: 1140, 法力值: 1790 },
  斯芬克丝: { 气血: 1070, 法力值: 1740 },
  拉维妮亚: { 气血: 1260, 法力值: 1800 },
  克茜拉: { 气血: 1290, 法力值: 1915 },
  奈亚: { 气血: 1280, 法力值: 1925 },
  胧: { 气血: 475, 法力值: 900 },
};

function clampSnapshotVital(value: unknown, max: number): number {
  const current = Number(value);
  return Number.isFinite(current) ? Math.min(max, Math.max(0, current)) : max;
}

/**
 * 修复固定神契古神被 AI 重建出的异常六维。
 *
 * - 旧版全 0 快照恢复固定六维并回满资源，同时写入固定上限；
 * - 非零错误快照恢复固定六维与上限，并将资源截断到上限，不会无故回血；
 * - 已与固定预设一致的快照保持不变。
 */
export function repairShenqiSnapshot(snapshot: ShenqiSnapshot, name: ShenqiGodName): boolean {
  const attributes = SHENQI_GOD_ATTRIBUTES[name];
  const maxVitals = SHENQI_MAX_VITALS[name];
  const allZero = Boolean(snapshot?.六维) && ATTRIBUTE_KEYS.every(key => Number(snapshot.六维?.[key]) === 0);
  const matchesCanonical =
    Boolean(snapshot?.六维) &&
    ATTRIBUTE_KEYS.every(key => Number(snapshot.六维?.[key]) === attributes[key]) &&
    Number(snapshot.气血上限) === maxVitals.气血 &&
    Number(snapshot.法力值上限) === maxVitals.法力值;
  if (matchesCanonical) return false;

  snapshot.六维 = { ...attributes };
  snapshot.气血上限 = maxVitals.气血;
  snapshot.法力值上限 = maxVitals.法力值;
  if (allZero) {
    snapshot.气血 = maxVitals.气血;
    snapshot.法力值 = maxVitals.法力值;
  } else {
    snapshot.气血 = clampSnapshotVital(snapshot.气血, maxVitals.气血);
    snapshot.法力值 = clampSnapshotVital(snapshot.法力值, maxVitals.法力值);
  }
  return true;
}

/** 兼容旧调用：仅迁移六维全 0 的神契快照。 */
export function repairZeroShenqiSnapshot(snapshot: ShenqiSnapshot, name: ShenqiGodName): boolean {
  if (!snapshot?.六维 || !ATTRIBUTE_KEYS.every(key => Number(snapshot.六维?.[key]) === 0)) return false;
  return repairShenqiSnapshot(snapshot, name);
}

export function getShenqiDescription(name: ShenqiGodName): string {
  const effect = SHENQI_EFFECTS[name];
  return `${effect.日常效果}\n${effect.六维加成}`;
}

export function applyCanonicalShenqiEffects(data: {
  古神列表?: Record<string, { 神契技能?: string; 神契描述?: string }>;
}): boolean {
  let changed = false;

  for (const [name, effect] of Object.entries(SHENQI_EFFECTS)) {
    const god = data.古神列表?.[name];
    if (!god) continue;

    const description = `${effect.日常效果}\n${effect.六维加成}`;
    if (god.神契技能 !== effect.技能) {
      god.神契技能 = effect.技能;
      changed = true;
    }
    if (god.神契描述 !== description) {
      god.神契描述 = description;
      changed = true;
    }
  }

  return changed;
}
